extern int nglGetScreenWidth();
extern int nglGetScreenHeight();

template <class T> void adjustSizes(T &x, T &y)
{
	x = (T) (x*(nglGetScreenWidth()/640.f));
	y = (T) (y*(nglGetScreenHeight()/480.f));
}

class Font
{
public:
	struct glyph_info
	{
		unsigned char ascii;
		unsigned int cell_x, cell_y;
		unsigned int cell_width, cell_height;
		unsigned int glyph_x, glyph_y;
		unsigned int glyph_width, glyph_height;
	};
	enum VERTJUST { VERTJUST_TOP, VERTJUST_CENTER, VERTJUST_BOTTOM };
	glyph_info* getGlyph(char c);
};

struct StringList
{
	char pad[8];
	float x;
	float y;
	char rest[3000];
};

class TrickBoxText
{
public:
	Font *font;
	char pad04[8];
	float x;
	float y;
	char pad14[8];
	Font::VERTJUST vJustify;
	char pad20[16];
	float scale;
	char pad34[3052];
	int numLines;
	int lineHeight;
	int width;
	int height;
	char pad0c30[4];
	StringList box_strings[10];

	void SetSize(const int w, const int h);
};

void TrickBoxText::SetSize(const int w, const int h)
{
	float	scale_x = scale, scale_y = scale;

	// Get hardware-dependent width and height.
	width = w;
	height = h;
	if (width < 0) width = 0;
	if (height < 0) height = 0;
	adjustSizes(width, height);

	// Get hardware-dependent font size.
	adjustSizes(scale_x, scale_y);
	lineHeight = int(font->getGlyph('A')->cell_height*scale_y);
	if (lineHeight == 0) lineHeight = 1;

	// Reposition onscreen text.
	for(int i = 0; i < numLines; i++)
	{
		StringList* tmp = &box_strings[i];

		// X is simple.
		tmp->x = x+(width/2);

		// Y is more complicated.
		if (vJustify == Font::VERTJUST_TOP)
			tmp->y = y+i*lineHeight;
		else
			tmp->y = (y+height-lineHeight) - i*lineHeight;
	}
}
